# ============= UNIT 7 END-OF-UNIT REVISION AIDS =============
add_cheatsheet("Unit 7 · Cheat Sheet","One-page revision reference",
    [("Performance tuning (S45)","Tune query → index → hardware; MEASURE first (EXPLAIN). Index columns in WHERE/JOIN/ORDER BY: reads faster, writes slower. Avoid SELECT *; filter early."),
     ("Security (S45)","Authentication = WHO; authorization = WHAT (least privilege). SQL injection → parameterized/prepared statements. Encryption at rest + in transit (TLS)."),
     ("Parallel vs distributed (S46)","Parallel = one site, more power. Distributed = many sites, one logical DB (locality, reliability, scale)."),
     ("Fragmentation & replication (S46)","Fragmentation SPLITS (horizontal = rows, vertical = columns); replication COPIES. Transparency hides location/fragmentation/replication. Use both together."),
     ("Warehousing (S47)","OLTP runs the business; OLAP analyzes it. Warehouse = integrated historical store (star schema), fed by ETL (Transform = the hard part). Mining finds unknown patterns."),
     ("BigData & NoSQL (S47)","3 Vs: Volume, Velocity, Variety. NoSQL: key-value (Redis) · document (MongoDB) · column (Cassandra) · graph (Neo4j) — complements SQL; pick per data shape.")])

add_glossary("Unit 7 · Glossary","Key terms — quick reference",
    [("Performance tuning","making the DB return correct answers faster on the same hardware."),
     ("Execution plan (EXPLAIN)","how the DBMS will run a query; used to find bottlenecks."),
     ("Index","auxiliary (B-tree) structure that finds rows without a full table scan."),
     ("Full table scan","reading every row because no useful index exists."),
     ("Query tuning","rewriting a query so the optimizer reads fewer rows."),
     ("Authentication","verifying WHO a user is (login, password, OTP)."),
     ("Authorization","deciding WHAT a user may do (GRANT/REVOKE, roles, least privilege)."),
     ("SQL injection","injecting malicious SQL via input; fixed by parameterized queries."),
     ("Encryption at rest / in transit","protecting stored data / data moving over the network (TLS)."),
     ("Parallel database","many processors/disks at ONE site working together."),
     ("Distributed database","data across MULTIPLE sites appearing as one logical DB."),
     ("Fragmentation","splitting a table across sites (horizontal = rows, vertical = columns)."),
     ("Replication","keeping copies of the same data at multiple sites."),
     ("Distribution transparency","hiding location/fragmentation/replication from the user."),
     ("OLTP","many small fast transactions — running the business."),
     ("OLAP","few large complex read queries over history — analysis."),
     ("Data warehouse","integrated, historical, read-mostly store for analysis (star schema)."),
     ("ETL","Extract → Transform (clean/standardize) → Load into the warehouse."),
     ("Star schema","a central fact table linked to dimension tables."),
     ("Data mining","discovering previously UNKNOWN patterns in large data."),
     ("BigData / 3 Vs","data beyond a traditional DBMS: Volume, Velocity, Variety."),
     ("NoSQL","non-relational stores: key-value, document, column-family, graph."),
     ("Least privilege","give each user only the access their job needs."),
     ("Single point of failure","one component whose failure stops the whole system.")])

